#include <stdio.h>

int main() {
    char word[6] = {'G', 'O', 'A', 'N', 'S', '\0'};
    char city[] = "Panjim";

    printf("%s\n", word);
    printf("%s has %zu bytes\n", city, sizeof(city));

    for (int i = 0; city[i] != '\0'; i++) {
        printf("city[%d] = %c\n", i, city[i]);
    }
    return 0;
}

